#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Class Connect: install or rebuild the home server deploy target (#23, ADR 0003).
#
#   deploy/setup-home-server.sh
#
# Run it on your laptop from a checkout of the repo, with `ssh wsl` and `gh` working.
# It installs the units and scripts from this checkout, so check out `dev` or `master` first.
# Each step that needs sudo opens an ssh session with a terminal and asks for your password once.
# It's safe to rerun: every step checks what's already there. Values you enter are kept in
# ~/.local/state/class-connect/server.env (mode 0600, never in the repo), so a rerun offers
# them again. Override with CC_SERVER=<ssh host> or CC_ENV_FILE=<path>.

REPO="ofeq-dev/class-connect"
SERVER="${CC_SERVER:-wsl}"
SERVER_USER="josh"                 # the units run as josh
APP_URL="https://cc.ofeq.dev"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REMOTE_DIR=".cache/class-connect-setup"   # relative to the server user's home
UNITS=(class-connect.service class-connect-backup.service class-connect-backup.timer)

# remote CMD runs CMD on the server without a terminal (no sudo prompts possible).
remote() { ssh -o BatchMode=yes "$SERVER" "$@"; }

# push_file LOCAL NAME copies a local file to ~/$REMOTE_DIR/NAME on the server (mode 0600).
push_file() {
  remote "umask 077 && mkdir -p $REMOTE_DIR && cat > $REMOTE_DIR/$2" < "$1"
}

# sudo_script NAME runs the bash script on stdin on the server, in a terminal so sudo can ask
# for the password. The script is uploaded first because a terminal session can't also read
# a script from stdin.
sudo_script() {
  local name="$1"
  remote "umask 077 && mkdir -p $REMOTE_DIR && cat > $REMOTE_DIR/$name"
  ssh -t "$SERVER" "bash $REMOTE_DIR/$name" </dev/tty
}

fail() { warn "$1"; printf '\n'; exit 1; }

# healthz prints the body of /healthz, or nothing.
healthz() { curl -fsS --max-time 8 "$APP_URL/healthz" 2>/dev/null || true; }

# http_code URL prints the HTTP status of URL (000 when nothing answers).
http_code() { curl -s -o /dev/null --max-time 8 -w '%{http_code}' "$1" 2>/dev/null || true; }

# tunnel_probe succeeds when $APP_URL reaches 127.0.0.1:3000 on the server. Before the first
# deploy nothing listens there, and with WSL's mirrored networking a closed localhost port times
# out instead of refusing, so Cloudflare just hangs. To get a clear answer, the probe serves a
# one-off token on 127.0.0.1:3000 for a few seconds and fetches it through the tunnel.
tunnel_probe() {
  if remote 'systemctl is-active --quiet class-connect.service'; then
    [[ "$(http_code "$APP_URL/healthz")" == 200 ]]; return
  fi
  local token="tunnel-probe-$RANDOM$RANDOM" body
  remote "d=\$(mktemp -d) && echo $token > \$d/healthz && cd \$d \
    && ( (timeout 20 python3 -m http.server 3000 --bind 127.0.0.1; rm -rf \$d) </dev/null >/dev/null 2>&1 &) \
    && sleep 1"
  body="$(curl -fsS --max-time 15 "$APP_URL/healthz" 2>/dev/null || true)"
  [[ "$body" == "$token" ]]
}

ACCEPT=()         # acceptance results for the closing summary
MERGED_SHA=""

run_wizard() {

TOTAL_STAGES=12
ENV_FILE="${CC_ENV_FILE:-${XDG_STATE_HOME:-$HOME/.local/state}/class-connect/server.env}"
mkdir -p "$(dirname "$ENV_FILE")"

banner "Class Connect: home server setup (#23)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight checks"
say "Checking this checkout, gh, and the server ($SERVER) before changing anything."
for unit in "${UNITS[@]}"; do
  [[ -f "$HERE/deploy/$unit" ]] || fail "deploy/$unit is missing; check out dev or master first."
done
[[ -f "$HERE/scripts/deploy.sh" ]] || fail "scripts/deploy.sh is missing; check out dev or master first."
grep -q '^Environment=FILES_DIR=' "$HERE/deploy/class-connect.service" \
  || fail "deploy/class-connect.service has no FILES_DIR line, so uploaded files would be lost on every deploy (#32)."
step "unit files and deploy script present, and FILES_DIR is set in the service ✓"
note "  (deploy/ from $(git -C "$HERE" log -1 --format='%h %s' -- deploy/ 2>/dev/null || echo 'this checkout'))"

command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || fail "gh is not installed or not signed in (run: gh auth login)."
step "gh signed in ✓"

if [[ ! -x "$HERE/node_modules/.bin/tsx" ]]; then
  warn "Local node_modules is missing; it's needed to hash the Lecturer password."
  if confirm "Run npm ci in $HERE now?"; then (cd "$HERE" && npm ci); else fail "Run npm ci, then rerun."; fi
fi
step "local tsx available for hashing the password ✓"

remote true 2>/dev/null || fail "ssh $SERVER failed. Check ~/.ssh/config and that the server is up."
remote_user="$(remote 'id -un')"
[[ "$remote_user" == "$SERVER_USER" ]] || fail "ssh $SERVER signs in as $remote_user, but the units run as $SERVER_USER."
step "ssh $SERVER works, as $SERVER_USER ✓"

# The unit runs /usr/bin/node, and deploys over ssh need node and npm on a non-login PATH.
node_report="$(remote 'n=$(command -v node || true); m=$(command -v npm || true); echo "${n:-none}|${m:-none}|$( [ -n "$n" ] && readlink -f "$n")|$( [ -n "$n" ] && node -p process.versions.node)"')"
IFS='|' read -r node_path npm_path node_real node_version <<<"$node_report"
if [[ "$node_path" == none || "$npm_path" == none ]]; then
  fail "node or npm is not on the server's non-interactive PATH. Install Node 22 from the system package manager (NodeSource), not nvm."
fi
if [[ "$node_real" == *"/.nvm/"* || "$node_path" != /usr/bin/node ]]; then
  warn "node on $SERVER is $node_path (→ $node_real), not /usr/bin/node."
  note "The service runs /usr/bin/node and the runner service never loads nvm. Install Node 22 system-wide"
  note "(NodeSource) so /usr/bin/node exists, or edit ExecStart in deploy/*.service to match."
  fail "Fix Node on the server, then rerun."
fi
IFS='.' read -r node_major node_minor _ <<<"$node_version"
if (( node_major < 22 || (node_major == 22 && node_minor < 12) )); then
  fail "Node on $SERVER is $node_version; package.json needs >=22.12."
fi
step "Node $node_version at /usr/bin/node, npm at $npm_path ✓"

port_owner="$(remote "ss -ltnpH 'sport = :3000' 2>/dev/null || true")"
if [[ -n "$port_owner" ]] && ! remote 'systemctl is-active --quiet class-connect.service'; then
  warn "Something else is already listening on port 3000 on $SERVER:"
  note "$port_owner"
  confirm "Continue anyway? (the app will fail to start until it's stopped)" || exit 1
fi
pause "All good. Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Protect the runner from fork pull requests"
say "The repo is public. A pull request from a fork runs the workflow file from that fork, so"
say "it could target the [self-hosted, wsl] runner and run code on the home server. GitHub can"
say "hold every outside contributor's fork-PR run until you approve it."
policy="$(gh api "repos/$REPO/actions/permissions/fork-pr-contributor-approval" --jq .approval_policy 2>/dev/null || echo unknown)"
if [[ "$policy" == all_external_contributors ]]; then
  step "already set: approval required for all outside contributors ✓"
elif confirm "Current policy is '$policy'. Require approval for all outside contributors now?"; then
  if gh api -X PUT "repos/$REPO/actions/permissions/fork-pr-contributor-approval" \
       -f approval_policy=all_external_contributors >/dev/null 2>&1; then
    step "set: approval required for all outside contributors ✓"
  else
    warn "The API call failed, so set it in the browser instead:"
    open_url "https://github.com/$REPO/settings/actions"
    step "Under 'Approval for running fork pull request workflows', choose the option that requires approval for all outside (external) contributors, then Save."
    pause "Press Enter once it's saved"
  fi
else
  SKIPPED+=("fork-PR approval for all outside contributors (Settings → Actions → General)")
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the server directories"
say "Creating these, owned by $SERVER_USER:"
step "/srv/class-connect/releases   (built releases and the current symlink)"
step "/var/lib/class-connect/files  (the database, plus uploaded Transcripts and Submissions)"
step "/mnt/d/class-connect-backups  (nightly and pre-deploy backups on D:)"
note "sudo will ask for your password on $SERVER."
sudo_script dirs.sh <<'EOF'
set -euo pipefail
sudo install -d -o josh -g josh /srv/class-connect /srv/class-connect/releases \
  /var/lib/class-connect /var/lib/class-connect/files
mkdir -p /mnt/d/class-connect-backups
touch /mnt/d/class-connect-backups/.write-test && rm /mnt/d/class-connect-backups/.write-test
stat -c '  %U:%G %n' /srv/class-connect /srv/class-connect/releases /var/lib/class-connect \
  /var/lib/class-connect/files /mnt/d/class-connect-backups
EOF
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Passwordless restart for deploys"
say "scripts/deploy.sh restarts the app with 'sudo -n systemctl', so $SERVER_USER needs a"
say "NOPASSWD rule for exactly restart, stop and start of class-connect.service, and nothing else."
sudo_script sudoers.sh <<'EOF'
set -euo pipefail
f="$(mktemp)"
cat > "$f" <<'RULE'
# Class Connect (#23): scripts/deploy.sh restarts the app, and a backup restore stops and starts it.
josh ALL=(root) NOPASSWD: /usr/bin/systemctl restart class-connect.service, /usr/bin/systemctl stop class-connect.service, /usr/bin/systemctl start class-connect.service
RULE
sudo visudo -cf "$f"
sudo install -m 0440 -o root -g root "$f" /etc/sudoers.d/class-connect
rm -f "$f"
EOF
if remote 'sudo -n -l /usr/bin/systemctl restart class-connect.service' >/dev/null 2>&1; then
  step "sudo -n systemctl restart class-connect.service is allowed without a password ✓"
else
  fail "The sudoers rule didn't take effect. Check /etc/sudoers.d/class-connect on $SERVER."
fi
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Lecturer sign-in"
say "The console's Lecturer password is stored only as a hash. The password itself isn't saved anywhere."
keep_hash=0
if _existing LECTURER_PASSWORD_HASH >/dev/null; then
  confirm "A Lecturer password hash is already saved. Keep it?" && keep_hash=1
fi
if (( keep_hash == 0 )); then
  while :; do
    PW1=""; PW2=""
    ask_secret PW1 "New Lecturer password:"
    ask_secret PW2 "Same password again:"
    if [[ -z "$PW1" ]]; then warn "Empty password; try again."; continue; fi
    if [[ "$PW1" != "$PW2" ]]; then warn "They don't match; try again."; continue; fi
    (( ${#PW1} >= 12 )) || warn "That's under 12 characters. This console is on the public internet."
    break
  done
  hash="$(cd "$HERE" && node_modules/.bin/tsx scripts/hash-password.ts "$PW1")"
  unset PW1 PW2
  [[ "$hash" == scrypt\$* ]] || fail "hash-password printed something unexpected."
  write_env LECTURER_PASSWORD_HASH "$hash"
fi

if _existing COOKIE_SECRET >/dev/null; then
  step "COOKIE_SECRET already saved; keeping it so signed-in sessions stay valid ✓"
else
  write_env COOKIE_SECRET "$(head -c 48 /dev/urandom | base64 | tr -d '\n/+=')"
fi

LECTURER_NAME=""
while :; do
  ask LECTURER_NAME "Lecturer name shown in the app (Enter for the default 'Lecturer'):"
  [[ "$LECTURER_NAME" != *\'* ]] && break
  warn "systemd can't read an apostrophe in this file; leave it out."
done
[[ -n "$LECTURER_NAME" ]] && write_env LECTURER_NAME "$LECTURER_NAME"
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "LLM settings (OpenRouter)"
if _existing OPENROUTER_API_KEY >/dev/null; then
  say "An OpenRouter key is already saved. Press Enter to keep it, or paste a new one."
else
  say "Create an OpenRouter API key for the app."
  open_url "https://openrouter.ai/settings/keys"
  step "Click 'Create API Key', name it 'class-connect-demo' (a credit limit is a good idea), then Create."
  step "Copy the key (it starts sk-or-v1-). It's shown only once."
fi
OPENROUTER_API_KEY=""
while :; do
  ask_secret OPENROUTER_API_KEY "OpenRouter API key:"
  [[ -n "$OPENROUTER_API_KEY" ]] && break
  warn "The key is required; paste it."
done
[[ "$OPENROUTER_API_KEY" == sk-or-* ]] || warn "That doesn't start with sk-or-; double-check it."
key_status="$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 \
  -H @<(printf 'Authorization: Bearer %s' "$OPENROUTER_API_KEY") https://openrouter.ai/api/v1/key || true)"
if [[ "$key_status" == 200 ]]; then
  step "OpenRouter accepted the key ✓"
else
  warn "OpenRouter answered $key_status for this key."
  confirm "Save it anyway?" || fail "Rerun with a working key."
fi
write_env OPENROUTER_API_KEY "$OPENROUTER_API_KEY"

LLM_ADAPTER=""
while :; do
  ask LLM_ADAPTER "LLM_ADAPTER, openrouter for real calls or fake for rehearsals (Enter for openrouter):"
  [[ -z "$LLM_ADAPTER" ]] && LLM_ADAPTER=openrouter
  [[ "$LLM_ADAPTER" == openrouter || "$LLM_ADAPTER" == fake ]] && break
  warn "Use openrouter or fake."
done
write_env LLM_ADAPTER "$LLM_ADAPTER"

default_review_model="$(sed -n 's/.*DEFAULT_REVIEW_MODEL = "\(.*\)";.*/\1/p' "$HERE/src/server/config.ts")"
say ""
say "Reviews try a pinned structured-output model first (#57). The default is"
say "${default_review_model:-set in src/server/config.ts}. Only set LLM_REVIEW_MODEL to override it."
LLM_REVIEW_MODEL=""
ask LLM_REVIEW_MODEL "LLM_REVIEW_MODEL (Enter keeps the default):"
[[ -n "$LLM_REVIEW_MODEL" ]] && write_env LLM_REVIEW_MODEL "$LLM_REVIEW_MODEL"
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Install /etc/class-connect.env and the systemd units"
# Keep any settings already on the server that this wizard doesn't manage (e.g. LLM_MODELS).
merged_env="$(mktemp)"; chmod 600 "$merged_env"
cat "$ENV_FILE" > "$merged_env"
current_env="$(remote 'cat /etc/class-connect.env 2>/dev/null || true')"
changed=(); kept=()
while IFS= read -r line; do
  [[ "$line" =~ ^([A-Z_][A-Z0-9_]*)= ]] || continue
  key="${BASH_REMATCH[1]}"
  new_line="$(grep -E "^${key}=" "$ENV_FILE" | tail -n1 || true)"
  if [[ -z "$new_line" ]]; then
    printf '%s\n' "$line" >> "$merged_env"; kept+=("$key")
  elif [[ "$new_line" != "$line" ]]; then
    changed+=("$key")
  fi
done <<<"$current_env"
if [[ -z "$current_env" ]]; then
  say "Creating /etc/class-connect.env (root:$SERVER_USER, mode 0640) with: $(grep -oE '^[A-Z_][A-Z0-9_]*' "$merged_env" | tr '\n' ' ')"
else
  (( ${#changed[@]} )) && warn "Values that will change on the server: ${changed[*]}"
  (( ${#kept[@]} )) && note "Kept as they are on the server: ${kept[*]}"
  (( ${#changed[@]} )) || step "No values change in /etc/class-connect.env."
fi
say "Installing ${UNITS[*]} from deploy/, enabling the service"
say "(it starts on the first deploy) and starting the nightly backup timer."
confirm "Install them on $SERVER now?" || { rm -f "$merged_env"; fail "Stopped before installing anything."; }
push_file "$merged_env" class-connect.env
rm -f "$merged_env"
for unit in "${UNITS[@]}"; do push_file "$HERE/deploy/$unit" "$unit"; done
sudo_script install.sh <<'EOF'
set -euo pipefail
cd ~/.cache/class-connect-setup
trap 'rm -f class-connect.env' EXIT
sudo install -m 0640 -o root -g josh class-connect.env /etc/class-connect.env
sudo install -m 0644 -o root -g root class-connect.service class-connect-backup.service \
  class-connect-backup.timer /etc/systemd/system/
sudo systemctl daemon-reload
sudo systemctl enable class-connect.service
sudo systemctl enable --now class-connect-backup.timer
# On a rerun with a release already live, pick up the new settings now.
if [ -e /srv/class-connect/current ]; then sudo systemctl restart class-connect.service; fi
EOF
remote 'systemctl is-enabled class-connect.service >/dev/null && systemctl is-active --quiet class-connect-backup.timer' \
  || fail "The units didn't install cleanly. Check 'systemctl status class-connect*' on $SERVER."
step "class-connect.service enabled, class-connect-backup.timer active ✓"
pause "Press Enter to continue"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub self-hosted runner"
say "The deploy job runs on [self-hosted, wsl]. Installing the runner in ~/actions-runner on"
say "$SERVER as a systemd service running as $SERVER_USER. It only makes outbound connections."
if remote 'test -f actions-runner/.runner'; then
  step "runner already registered ✓"
else
  version="$(gh api repos/actions/runner/releases/latest --jq .tag_name)"; version="${version#v}"
  token="$(gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token)"
  [[ -n "$version" && -n "$token" ]] || fail "Couldn't get the runner release or a registration token from GitHub."
  say "Downloading runner v$version and registering it with the label 'wsl'…"
  remote "bash -s -- $version $token $REPO" <<'EOF'
set -euo pipefail
version="$1" token="$2" repo="$3"
mkdir -p ~/actions-runner && cd ~/actions-runner
if [ ! -x ./config.sh ]; then
  curl -fsSL -o runner.tgz "https://github.com/actions/runner/releases/download/v$version/actions-runner-linux-x64-$version.tar.gz"
  tar xzf runner.tgz && rm runner.tgz
fi
./config.sh --unattended --replace --url "https://github.com/$repo" --token "$token" \
  --name "$(hostname)" --labels wsl --work _work
EOF
  unset token
fi
note "sudo will ask for your password to install the runner service."
sudo_script runner-service.sh <<'EOF'
set -euo pipefail
cd ~/actions-runner
[ -f .service ] || sudo ./svc.sh install josh
sudo ./svc.sh start
EOF
runner_status=""
for _ in $(seq 1 20); do
  runner_status="$(gh api "repos/$REPO/actions/runners" \
    --jq '[.runners[] | select(any(.labels[]; .name == "wsl"))][0].status // ""' 2>/dev/null || true)"
  [[ "$runner_status" == online ]] && break
  sleep 3
done
[[ "$runner_status" == online ]] || fail "GitHub doesn't show a 'wsl' runner online (status: ${runner_status:-none}). Check: ssh $SERVER 'cd actions-runner && sudo ./svc.sh status'"
step "GitHub shows the runner online with the label wsl ✓"
pause "Press Enter to continue"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Tunnel route for cc.ofeq.dev"
say "Checking whether $APP_URL already reaches 127.0.0.1:3000 on $SERVER…"
if tunnel_probe; then
  step "$APP_URL reaches 127.0.0.1:3000 on $SERVER through the tunnel ✓"
else
  say "The tunnel on $SERVER is managed from the Cloudflare dashboard (cloudflared runs with a token)."
  open_url "https://one.dash.cloudflare.com/"
  step "Pick the account, then Networks → Tunnels (or Networks → Connectors → Cloudflare Tunnels)."
  step "Open the tunnel whose connector is $SERVER's machine (status Healthy) → Edit / Configure."
  step "Tab 'Public Hostname' (newer UI: 'Published application routes') → Add."
  step "Subdomain: cc   Domain: ofeq.dev   Path: (empty)"
  step "Service type: HTTP   URL: localhost:3000   → Save."
  note "The check serves a test page on 127.0.0.1:3000 for a few seconds, since the app isn't deployed yet."
  while :; do
    pause "Press Enter once it's saved to check"
    if tunnel_probe; then
      step "$APP_URL reaches 127.0.0.1:3000 on $SERVER through the tunnel ✓"; break
    fi
    case "$(http_code "$APP_URL/healthz")" in
      000) warn "No answer from $APP_URL (DNS not there yet, or the route points somewhere else)." ;;
      530) warn "Cloudflare answered 530: the hostname exists but isn't reaching a running tunnel." ;;
      *)   warn "$APP_URL answers, but not from 127.0.0.1:3000. Check the route's URL is localhost:3000." ;;
    esac
    confirm "Check again?" || { SKIPPED+=("Cloudflare route cc.ofeq.dev → http://localhost:3000"); break; }
  done
fi
pause "Press Enter to continue"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Merge PR #43 and watch the first deploy"
pr_state="$(gh pr view 43 --repo "$REPO" --json state --jq .state)"
if [[ "$pr_state" == OPEN ]]; then
  say "PR #43 merges dev into master. That push runs check, then deploy on the home server."
  gh pr checks 43 --repo "$REPO" 2>/dev/null | sed 's/^/    /' || true
  if confirm "Merge PR #43 now with a merge commit (keeps dev and master in step)?"; then
    gh pr merge 43 --repo "$REPO" --merge
    pr_state=MERGED
  fi
fi
if [[ "$pr_state" == MERGED ]]; then
  MERGED_SHA="$(gh pr view 43 --repo "$REPO" --json mergeCommit --jq .mergeCommit.oid)"
  say "Merged as $MERGED_SHA. Waiting for its workflow run…"
  run_id=""
  for _ in $(seq 1 30); do
    run_id="$(gh run list --repo "$REPO" --workflow check.yml --event push --commit "$MERGED_SHA" \
      --json databaseId --jq '.[0].databaseId // ""' 2>/dev/null || true)"
    [[ -n "$run_id" ]] && break
    sleep 4
  done
  [[ -n "$run_id" ]] || fail "No check.yml run appeared for $MERGED_SHA. Look at https://github.com/$REPO/actions"
  note "https://github.com/$REPO/actions/runs/$run_id"
  if ! gh run watch "$run_id" --repo "$REPO" --exit-status; then
    ACCEPT+=("✗ deploy run $run_id failed")
    fail "The run failed. See: gh run view $run_id --repo $REPO --log-failed"
  fi
  body="$(healthz)"
  if [[ "$body" == *"\"sha\":\"$MERGED_SHA\""* ]]; then
    step "$APP_URL/healthz reports $MERGED_SHA ✓"
    ACCEPT+=("✓ a merge to master deployed and /healthz shows $MERGED_SHA")
  else
    ACCEPT+=("✗ /healthz doesn't show the merged SHA")
    fail "/healthz answered '${body:-nothing}', not $MERGED_SHA."
  fi
else
  warn "PR #43 is $pr_state, not merged, so nothing is deployed: cc.ofeq.dev has no app behind it,"
  warn "and the rollback drill and first backup can't run either. Rerun the wizard to merge."
  SKIPPED+=("merge PR #43 and confirm /healthz shows the merged SHA (rerun the wizard)")
fi
pause "Press Enter to continue"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Rollback drill: a broken health check rolls back and fails"
if [[ -z "$MERGED_SHA" ]]; then
  warn "Skipped: needs the first deploy from stage 10."
  SKIPPED+=("rollback drill (needs a live release)")
else
  git -C "$HERE" fetch -q origin
  old_sha="$(git -C "$HERE" rev-parse --verify -q "${MERGED_SHA}^2~1" || true)"
  say "Runs the same scripts/deploy.sh the deploy job runs, on $SERVER, for an older dev commit,"
  say "with the health URL pointed at a path that never reports a SHA. Expected result: it builds,"
  say "switches, fails the health check, rolls back to $MERGED_SHA and exits non-zero"
  say "(a red run). The build takes a few minutes, and the older build serves for about 10s."
  drill_sha=""
  ask drill_sha "Older commit to deploy for the drill (Enter for ${old_sha:0:12}):"
  [[ -z "$drill_sha" ]] && drill_sha="$old_sha"
  old_sha="$drill_sha"
  [[ "$old_sha" =~ ^[0-9a-f]{7,40}$ ]] || fail "Not a commit SHA: $old_sha"
  if confirm "Run the drill now?"; then
    drill_log="$(mktemp)"
    drill_rc=0
    remote "CC_HEALTH_URL=$APP_URL/healthz-drill-broken CC_HEALTH_TIMEOUT=10 bash -s -- $old_sha" \
      < "$HERE/scripts/deploy.sh" 2>&1 | tee "$drill_log" || drill_rc=$?
    # deploy.sh exits right after the rollback restart, before the app is listening again.
    for _ in $(seq 1 15); do
      body="$(healthz)"
      [[ "$body" == *"\"sha\":\"$MERGED_SHA\""* ]] && break
      sleep 2
    done
    if (( drill_rc != 0 )) && grep -q "rolled back to $MERGED_SHA" "$drill_log" \
       && [[ "$body" == *"\"sha\":\"$MERGED_SHA\""* ]]; then
      step "deploy exited $drill_rc (red), rolled back, and /healthz still reports $MERGED_SHA ✓"
      ACCEPT+=("✓ a broken health check rolled back and the deploy failed (exit $drill_rc)")
    else
      ACCEPT+=("✗ rollback drill: exit $drill_rc, healthz '${body:-nothing}'")
      warn "The drill didn't behave as expected (exit $drill_rc). Log: $drill_log"
      warn "Check what's live: curl $APP_URL/healthz"
    fi
  else
    SKIPPED+=("rollback drill")
  fi
fi
pause "Press Enter to continue"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Backups: timer active and a first backup on D:"
if ! remote 'test -e /srv/class-connect/current'; then
  # The backup runs dist/server/backup.js from the live release, so it can't run before a deploy.
  warn "Skipped the backup run: nothing is deployed yet (no /srv/class-connect/current)."
else
  note "sudo will ask for your password to run one backup now."
  sudo_script backup.sh <<'EOF' || warn "The backup failed; its log is above."
sudo systemctl start class-connect-backup.service || status=$?
journalctl -u class-connect-backup.service -n 5 --no-pager -o cat || true
exit "${status:-0}"
EOF
fi
timer_state="$(remote 'systemctl is-active class-connect-backup.timer' || true)"
remote 'systemctl list-timers class-connect-backup.timer --no-pager' | sed 's/^/    /' || true
backups="$(remote 'ls -1t /mnt/d/class-connect-backups 2>/dev/null | grep -v "^\." || true')"
if [[ "$timer_state" == active && -n "$backups" ]]; then
  step "timer active; newest backup: $(head -n1 <<<"$backups") ✓"
  ACCEPT+=("✓ backup timer active and a backup exists in /mnt/d/class-connect-backups")
else
  ACCEPT+=("✗ backups: timer '$timer_state', backup files: ${backups:+yes}${backups:-none}")
  warn "Timer is '$timer_state'; backup files on D: ${backups:+yes}${backups:-none}. See: journalctl -u class-connect-backup.service"
fi
say ""
warn "Backups cover only the database, not FILES_DIR (/var/lib/class-connect/files)."
note "Uploaded Transcripts and Submissions survive deploys but aren't copied to D:."
note "Acceptable for the demo; worth a follow-up ticket."

if [[ "${#ACCEPT[@]}" -eq 3 && "${ACCEPT[*]}" != *"✗"* ]] \
   && [[ "$(gh issue view 23 --repo "$REPO" --json state --jq .state)" == OPEN ]]; then
  say ""
  if confirm "All three acceptance checks passed. Close #23 with a summary comment?"; then
    gh issue close 23 --repo "$REPO" --comment "$(printf 'Installed with deploy/setup-home-server.sh.\n\n%s\n- %s\n- %s\n- %s' \
      'Acceptance:' "${ACCEPT[0]#✓ }" "${ACCEPT[1]#✓ }" "${ACCEPT[2]#✓ }")" >/dev/null && step "closed #23 ✓"
  fi
fi
pause "Press Enter to finish"

finish
if (( ${#ACCEPT[@]} )); then
  printf '  %sAcceptance (#23):%s\n' "$BOLD" "$RESET"
  for a in "${ACCEPT[@]}"; do note "  $a"; done
  printf '\n'
fi
}

run_wizard "$@"; exit
